import{_ as a,o as s,c as i,a0 as t}from"./chunks/framework.B6reNh8h.js";const k=JSON.parse('{"title":"Deep links","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/deep-links.md","filePath":"tutorials/deep-links.md"}'),o={name:"tutorials/deep-links.md"};function n(d,e,p,r,l,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="deep-links" tabindex="-1">Deep links <a class="header-anchor" href="#deep-links" aria-label="Permalink to &quot;Deep links&quot;">​</a></h1><p>Every view has a stable <code>&lt;driver&gt;:&lt;view&gt;</code> ref. On the CLI it is an argument; on the web it is a URL — the same link agents and humans can drop into PRs, issues, and handoffs.</p><h2 id="the-ref" tabindex="-1">The ref <a class="header-anchor" href="#the-ref" aria-label="Permalink to &quot;The ref&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pavo view demo:board</span></span>
<span class="line"><span>demo:board  →  route /demo/board  →  ViewSpec { id: &quot;board&quot; }</span></span></code></pre></div><p><code>pavo views</code> lists every ref; <code>pavo view --help</code> covers the CLI flags (<code>--param</code>, <code>--format</code>, <code>--json</code>).</p><h2 id="params-in-urls" tabindex="-1">Params in URLs <a class="header-anchor" href="#params-in-urls" aria-label="Permalink to &quot;Params in URLs&quot;">​</a></h2><p>Views take params (<code>--param k=v</code> on the CLI). In URLs they can be carried three ways — all normalize to the same <code>param.&lt;k&gt;=&lt;v&gt;</code> pairs the bridge API understands:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/view/myco:item/id=T-001/verbose        path segments: one k=v each</span></span>
<span class="line"><span>/view/myco:item?id=T-001&amp;verbose        bare query keys (no prefix)</span></span>
<span class="line"><span>/view/myco:item?param.id=T-001          legacy param.* form (still works)</span></span></code></pre></div><p>Grammar details (parsed by <code>web/app/utils/view-link.ts</code>; the no-build <code>/view/</code> stub in <code>pavo serve</code> speaks the same rules):</p><ul><li>The <strong>first</strong> path segment after <code>/view/</code> is the <code>&lt;driver&gt;:&lt;view&gt;</code> ref (the colon may be percent-encoded). Every later segment is one param: <code>key=value</code>, split at the <strong>first</strong> <code>=</code> (values may contain <code>=</code>); a bare <code>key</code> means an empty-string value; empty keys are dropped. So <code>/view/myco:item/T-001</code> sets param <code>T-001</code> to <code>&quot;&quot;</code> — write <code>/view/myco:item/id=T-001</code> for a real param.</li><li>Query keys are params too: bare <code>?k=v</code>, plus the legacy <code>?param.k=v</code> (prefix stripped).</li><li>Precedence, lowest → highest: <strong>path segments &lt; bare query keys &lt; <code>param.*</code> keys</strong> — the bridge merges last-wins, so later sources override earlier ones on a key collision.</li><li>Values parse as JSON when possible (<code>n=42</code>, <code>ok=true</code>, <code>j={…}</code>), else strings — identical to <code>--param</code> / <code>/api/view?param.*</code>.</li></ul><h2 id="serving-the-links" tabindex="-1">Serving the links <a class="header-anchor" href="#serving-the-links" aria-label="Permalink to &quot;Serving the links&quot;">​</a></h2><p><code>pavo serve</code> prints <code>listening http://127.0.0.1:&lt;port&gt;</code>; open the printed URL for the dashboard, or append a deep link directly:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:7420/view/demo%3Aboard</span></span>
<span class="line"><span>http://127.0.0.1:7420/view/demo:board/status=open</span></span></code></pre></div><p>With <code>cd web &amp;&amp; npm run build</code> the bridge serves the Nuxt app; without a build it serves a built-in landing page that still understands <code>/view/</code> links.</p><h2 id="cli-equivalents" tabindex="-1">CLI equivalents <a class="header-anchor" href="#cli-equivalents" aria-label="Permalink to &quot;CLI equivalents&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:board</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status=open</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:deps</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # TUI deep link (falls back to text off-TTY)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;localhost:7420/api/view?ref=demo:board&amp;param.status=open&#39;</span></span></code></pre></div><p>The <code>param.*</code> query convention is what the <code>/api/view</code> endpoint already speaks — URL path segments and bare query keys are normalized into it before the bridge sees them.</p>`,17)])])}const m=a(o,[["render",n]]);export{k as __pageData,m as default};
